//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is safe to retry.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry with the zero-based `retry_number`.
    /// Delay growth is capped before multiplication can overflow.
    pub fn delay_for_retry(&self, retry_number: u32) -> u64 {
        if self.base_delay_ms >= self.max_delay_ms {
            return self.max_delay_ms;
        }

        let mut delay = self.base_delay_ms;
        for _ in 0..retry_number.min(64) {
            delay = delay.saturating_mul(2).min(self.max_delay_ms);
            if delay == self.max_delay_ms {
                break;
            }
        }
        delay
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_saturates_without_overflow() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: u64::MAX / 2 + 1,
            max_delay_ms: u64::MAX,
        };

        assert_eq!(config.delay_for_retry(1), u64::MAX);
        assert_eq!(config.delay_for_retry(u32::MAX), u64::MAX);

        let small_base = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: 1,
            max_delay_ms: 1_000,
        };
        assert_eq!(small_base.delay_for_retry(u32::MAX), 1_000);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    // `retry_number` is also the zero-based exponent for the next delay.
    for attempt in 0..config.max_attempts {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() => return Err(error),
            Err(error) if attempt + 1 == config.max_attempts => return Err(error),
            Err(_) => sleeper.sleep_ms(config.delay_for_retry(attempt)),
        }
    }

    // A zero-attempt configuration is invalid according to the config contract.
    Err(RetryError::Permanent(
        "max_attempts must be at least 1".to_string(),
    ))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms: 10,
            max_delay_ms: 25,
        }
    }

    #[test]
    fn retries_transient_errors_and_counts_first_call() {
        let mut calls = 0;
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(4), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("temporary".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("temporary".into())));
        assert_eq!(calls, 4);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let mut calls = 0;
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(4), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn zero_attempts_return_configuration_error_without_calling_job() {
        let mut calls = 0;
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(0), &mut sleeper, || {
            calls += 1;
            Ok(())
        });

        assert_eq!(
            result,
            Err(RetryError::Permanent(
                "max_attempts must be at least 1".into()
            ))
        );
        assert_eq!(calls, 0);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn succeeds_after_transient_failures() {
        let mut calls = 0;
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(4), &mut sleeper, || {
            calls += 1;
            if calls == 3 {
                Ok(())
            } else {
                Err(RetryError::Transient("temporary".into()))
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_runner_retries_transient_failures_with_bounded_delays() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 5,
        max_delay_ms: 12,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls == 4 {
            Ok(())
        } else {
            Err(RetryError::Transient("temporary outage".into()))
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps, vec![5, 10, 12]);
}

#[test]
fn public_runner_does_not_retry_permanent_failures() {
    let config = RetryConfig {
        max_attempts: 3,
        base_delay_ms: 1,
        max_delay_ms: 10,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("invalid request".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid request".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}
